// Hugo/Ariel dataset: genus-2 curves over Q(sqrt d) with A[l]^ss = 1 + chi_l + sigma
// (l = 11 or 13, from a torsion point).  Entry: < d, l, label, fc, hc, condnorm, condc >
//   fc/hc : coeff lists, each [u,v] = u + v*a  (a = sqrt d);  curve  y^2 + h y = f
//   condnorm : stated prime-to-2 conductor norm
//   condc    : conductor ideal generator [u,v] over Q(sqrt2) (given); [0,0] over Q(sqrt3) (unknown)
torsion_data := [* *];
d2 := function(l,lab,fc,hc,N,cc) return <2,l,lab,fc,hc,N,cc>; end function;
d3 := function(l,lab,fc,hc,N)    return <3,l,lab,fc,hc,N,[0,0]>; end function;

